for(const p of presets)Object.assign(p,profiles[p.id]);
export function buildPreset(id,config){
 const p=presets.find(p=>p.id===id);if(!p)throw new Error('Unknown preset');
 if(id==='break-retest' && (config.side==='BOTH'||!Number.isFinite(config.level)||config.level<=0))throw new Error((globalThis.SnaapI18n?.text("Break & Retest ต้องระบุระดับราคามากกว่า 0 และเลือกฝั่งเดียว") ?? "Break & Retest ต้องระบุระดับราคามากกว่า 0 และเลือกฝั่งเดียว"));
 const t=config.timeframe??p.frame;
 const i=(name,period,extra={})=>({kind:'INDICATOR',name,period,timeframe:t,...extra});
 const price={kind:'PRICE',field:'close',timeframe:t};
 const n=value=>({kind:'CONSTANT',value});
 const c=(left,op,right)=>({kind:'COMPARE',left,op,right});
 const and=(...children)=>({kind:'GROUP',op:'AND',children});
 const branch=short=>{
  const up=short?'CROSS_BELOW':'CROSS_ABOVE',down=short?'CROSS_ABOVE':'CROSS_BELOW',gt=short?'<':'>';
  let entry,exit,stages=[];
  if(id==='break-retest'){
   const level=n(config.level);
   entry=c(price,up,level);exit=c(price,short?'>':'<',level);
   stages=[{condition:and(c({...price,field:short?'high':'low'},short?'>=':'<=',level),c(price,gt,level)),withinBars:10},{condition:{kind:'HOLD',bars:2,condition:c(price,gt,level)},withinBars:5}];
  }
  if(id==='trend'){entry=and(c(price,up,i('EMA',20)),c(price,gt,i('EMA',200)));exit=c(price,down,i('EMA',20));}
  if(id==='cross'){entry=c(i('EMA',20),up,i('EMA',50));exit=c(i('EMA',20),down,i('EMA',50));}
  if(id==='momentum'){entry=and(c(i('RSI',14),up,n(50)),c(price,gt,i('EMA',50)));exit=c(i('RSI',14),down,n(50));}
  if(id==='rebound'){entry=c(i('RSI',14),short?'CROSS_BELOW':'CROSS_ABOVE',n(short?70:30));exit=c(i('RSI',14),short?'CROSS_BELOW':'CROSS_ABOVE',n(50));}
  if(id==='bands'){entry=and(c(price,up,i(short?'BB_LOWER':'BB_UPPER',20,{deviation:2})),c(i('VOLUME_RATIO',20),'>',n(1.5)));exit=c(price,down,i('BB_MIDDLE',20));}
  if(id==='supertrend'){const st=i('SUPERTREND_DIRECTION',10,{params:{factor:3}});entry=c(st,up,n(0));exit=c(st,down,n(0));}
  return {entry,exit,stages,cooldownBars:3};
 };
 const side=config.market==='Spot'?'SPOT':config.side;
 const pairs=[...(config.pairs??[config.pair])];
 const spec={schemaVersion:2,name:`${p.title} · ${pairs.length===1?pairs[0]:pairs.length+(globalThis.SnaapI18n?.text(" คู่") ?? " คู่")} · ${side}`,exchange:[config.exchange],market:config.market,side,pairs,timeframe:t,...branch(side==='SHORT'),destinations:[]};
 if(side==='BOTH')spec.short=branch(true);
 return spec;
}
export function describePreset(spec){
 const operand=o=>o.kind==='CONSTANT'?String(o.value):o.kind==='PRICE'?`${{close:(globalThis.SnaapI18n?.text("ราคาปิด") ?? "ราคาปิด"),low:(globalThis.SnaapI18n?.text("ราคาต่ำสุด") ?? "ราคาต่ำสุด"),high:(globalThis.SnaapI18n?.text("ราคาสูงสุด") ?? "ราคาสูงสุด")}[o.field]??o.field} (${o.timeframe})`:`${o.name} ${o.period}${o.params?.factor?' / '+o.params.factor:''} (${o.timeframe})`;
 const condition=c=>c.kind==='HOLD'?`${condition(c.condition)}${(globalThis.SnaapI18n?.text(" ต่อเนื่อง ") ?? " ต่อเนื่อง ")}${c.bars}${(globalThis.SnaapI18n?.text(" แท่ง") ?? " แท่ง")}`:c.kind==='GROUP'?c.children.map(condition).join(c.op==='AND'?(globalThis.SnaapI18n?.text(" และ ") ?? " และ "):(globalThis.SnaapI18n?.text(" หรือ ") ?? " หรือ ")):`${operand(c.left)} ${{CROSS_ABOVE:(globalThis.SnaapI18n?.text("ตัดขึ้นเหนือ") ?? "ตัดขึ้นเหนือ"),CROSS_BELOW:(globalThis.SnaapI18n?.text("ตัดลงใต้") ?? "ตัดลงใต้"),'>':(globalThis.SnaapI18n?.text("มากกว่า") ?? "มากกว่า"),'<':(globalThis.SnaapI18n?.text("น้อยกว่า") ?? "น้อยกว่า")}[c.op]??c.op} ${operand(c.right)}`;
 const lines=[`${spec.exchange[0]} · ${spec.pairs.join(', ')} · ${spec.market} · ${spec.side} · ${spec.timeframe}`,`${(globalThis.SnaapI18n?.text("เข้า") ?? "เข้า")}${spec.side==='BOTH'?' Long':''}: ${condition(spec.entry)}`,`${(globalThis.SnaapI18n?.text("ออก") ?? "ออก")}${spec.side==='BOTH'?' Long':''}: ${condition(spec.exit)}`];
 if(spec.short)lines.push(`${(globalThis.SnaapI18n?.text("เข้า Short: ") ?? "เข้า Short: ")}${condition(spec.short.entry)}`,`${(globalThis.SnaapI18n?.text("ออก Short: ") ?? "ออก Short: ")}${condition(spec.short.exit)}`);
 spec.stages.forEach((s,i)=>lines.push(`${(globalThis.SnaapI18n?.text("รอยืนยัน ") ?? "รอยืนยัน ")}${i+1}: ${condition(s.condition)}${(globalThis.SnaapI18n?.text(" ภายใน ") ?? " ภายใน ")}${s.withinBars}${(globalThis.SnaapI18n?.text(" แท่ง") ?? " แท่ง")}`));
 lines.push((globalThis.SnaapI18n?.text("พัก 3 แท่งหลังจบวงจร · ตรวจแท่งปิด · เป็นสัญญาณ ไม่ส่งออเดอร์") ?? "พัก 3 แท่งหลังจบวงจร · ตรวจแท่งปิด · เป็นสัญญาณ ไม่ส่งออเดอร์"));
 return lines.join('\n');
}
